"""Generated by _tools/web_kit.py: hosted API and web app tests (identical in every product)."""

import base64
import contextlib
import hashlib
import hmac
import http.client
import io
import json
import os
import pathlib
import tempfile
import threading
import time
import unittest
import urllib.error
import urllib.request
import zipfile

from vibe_lube import web
from vibe_lube._webspec import SPEC

ROOT = pathlib.Path(__file__).resolve().parent.parent
EXAMPLES = json.loads((ROOT / "tests" / "web_examples.json").read_text(encoding="utf-8"))


class WebAppTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        os.environ["PYTHONPATH"] = (
            str(ROOT) + os.pathsep + os.environ.get("PYTHONPATH", "")
        )  # subprocess finds the package
        cls.tmp = tempfile.TemporaryDirectory()
        web.Handler.log_message = lambda *args: None  # keep test output readable
        cls.srv = web.make_server("127.0.0.1", 0, pathlib.Path(cls.tmp.name) / "data")
        cls.url = f"http://127.0.0.1:{cls.srv.server_address[1]}"
        threading.Thread(target=cls.srv.serve_forever, daemon=True).start()

    @classmethod
    def tearDownClass(cls):
        cls.srv.shutdown()
        cls.srv.server_close()
        cls.tmp.cleanup()

    def call(self, path, body=None, raw=None):
        data = raw if raw is not None else (None if body is None else json.dumps(body).encode("utf-8"))
        req = urllib.request.Request(self.url + path, data=data, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=90) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            with e:
                return e.code, e.headers, e.read()

    def test_health_spec_and_app_page(self):
        status, _, body = self.call("/healthz")
        self.assertEqual((status, json.loads(body)["status"]), (200, "ok"))
        status, headers, body = self.call("/")
        self.assertEqual(status, 200)
        self.assertIn("default-src 'none'", headers["Content-Security-Policy"])
        page = body.decode("utf-8")
        for op in SPEC["ops"]:
            self.assertIn(f'data-op="{op["id"]}"', page)
        self.assertEqual(self.call("/app.js")[0], 200)
        self.assertEqual(json.loads(self.call("/api/spec")[2])["name"], SPEC["name"])

    def test_every_documented_command_works_over_the_api(self):
        self.assertTrue(EXAMPLES, "no documented commands to exercise")
        for ex in EXAMPLES:
            with self.subTest(op=ex["op"]):
                status, _, body = self.call(f"/api/{ex['op']}", ex["payload"])
                res = json.loads(body)
                self.assertEqual(status, 200, res)
                self.assertIn(res["exit_code"], (0, 1), res)
                self.assertTrue(res.get("stdout", "").strip() or res.get("files"), res)
                self.assertNotIn("Traceback", res.get("stdout", "") + res.get("error", ""))

    def test_unknown_commands_fields_and_bad_json_are_rejected(self):
        self.assertEqual(self.call("/api/not-a-command", {})[0], 404)
        op = SPEC["ops"][0]["id"]
        self.assertEqual(self.call(f"/api/{op}", {"definitely_not_a_field": 1})[0], 400)
        self.assertEqual(self.call(f"/api/{op}", raw=b"[1, 2")[0], 400)

    def test_oversized_body_is_refused(self):
        conn = http.client.HTTPConnection("127.0.0.1", self.srv.server_address[1], timeout=10)
        conn.putrequest("POST", f"/api/{SPEC['ops'][0]['id']}")
        conn.putheader("Content-Length", str(web.MAX_BODY + 1))
        conn.endheaders()
        self.assertEqual(conn.getresponse().status, 413)
        conn.close()

    def test_client_cannot_name_a_server_path(self):
        for op in SPEC["ops"]:
            for f in op["fields"]:
                if f["kind"] in ("file", "dir"):
                    status, _, body = self.call(f"/api/{op['id']}", {f["dest"]: "/etc/passwd"})
                    self.assertEqual(status, 400, body)
                    return
        self.skipTest("this product takes no file or folder inputs")

    def test_zip_path_traversal_is_blocked(self):
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, "w") as z:
            z.writestr("../../escape.txt", "x")
        upload = {"base64": base64.b64encode(buf.getvalue()).decode()}
        with tempfile.TemporaryDirectory() as t, self.assertRaises(web.BadRequest):
            web._write_upload({"dest": "d", "kind": "dir"}, upload, pathlib.Path(t))

    def test_api_keys_rate_limit_and_metering(self):
        with tempfile.TemporaryDirectory() as t:
            srv = web.make_server("127.0.0.1", 0, pathlib.Path(t), env_keys="sk_test_one", rate=2)
            threading.Thread(target=srv.serve_forever, daemon=True).start()
            url, op = f"http://127.0.0.1:{srv.server_address[1]}/api/", SPEC["ops"][0]["id"]

            def post(key=None):
                headers = {"Content-Type": "application/json", **({"Authorization": f"Bearer {key}"} if key else {})}
                req = urllib.request.Request(url + op, data=b"{}", headers=headers)
                try:
                    with urllib.request.urlopen(req, timeout=90) as r:
                        return r.status
                except urllib.error.HTTPError as e:
                    with e:
                        return e.code

            try:
                self.assertEqual(post(), 401)
                self.assertEqual(post("sk_wrong"), 401)
                self.assertIn(post("sk_test_one"), (200, 400))  # 400 = valid key, empty payload for this command
                post("sk_test_one")
                self.assertEqual(post("sk_test_one"), 429)
                usage = web.Gate(pathlib.Path(t)).usage()
                self.assertEqual(usage["env-1"]["calls"], 2)
                self.assertEqual(usage["unauthenticated"]["calls"], 2)
            finally:
                srv.shutdown()
                srv.server_close()

    def test_created_keys_are_hashed_and_revocable(self):
        with tempfile.TemporaryDirectory() as t:
            gate = web.Gate(pathlib.Path(t))
            kid, key = gate.create("acme")
            self.assertNotIn(key, (pathlib.Path(t) / "api-keys.json").read_text(encoding="utf-8"))
            self.assertEqual(gate.identify(f"Bearer {key}"), kid)
            gate.revoke(kid)
            self.assertIsNone(gate.identify(f"Bearer {key}"))

    def test_public_bind_without_keys_is_refused(self):
        with tempfile.TemporaryDirectory() as t:
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                code = web.main(["--host", "0.0.0.0", "--port", "0", "--data-dir", t])
        self.assertEqual(code, 2)
        self.assertIn("refusing", err.getvalue())

    def test_stripe_purchase_issues_one_key_and_cancellation_revokes_it(self):
        env = {
            "STRIPE_SECRET_KEY": "sk_test_x",
            "STRIPE_WEBHOOK_SECRET": "whsec_test",
            "STRIPE_PRICES": "starter=price_1",
            "PUBLIC_URL": "https://example.test",
        }
        with tempfile.TemporaryDirectory() as t:
            srv = web.make_server("127.0.0.1", 0, pathlib.Path(t), env=env)
            billing = srv.RequestHandlerClass.billing
            sent = {}
            billing._stripe = lambda path, form: sent.update(form) or {"url": "https://checkout.test/s"}
            threading.Thread(target=srv.serve_forever, daemon=True).start()
            base = f"http://127.0.0.1:{srv.server_address[1]}"

            def hook(event, secret="whsec_test", ts=None):
                body = json.dumps(event).encode()
                ts = int(time.time()) if ts is None else ts
                sig = hmac.new(secret.encode(), f"{ts}.".encode() + body, hashlib.sha256).hexdigest()
                req = urllib.request.Request(
                    base + "/billing/webhook", data=body, headers={"Stripe-Signature": f"t={ts},v1={sig}"}
                )
                try:
                    with urllib.request.urlopen(req, timeout=30) as r:
                        return r.status
                except urllib.error.HTTPError as e:
                    with e:
                        return e.code

            try:
                self.assertIn(b"Subscribe", urllib.request.urlopen(base + "/pricing", timeout=30).read())
                conn = http.client.HTTPConnection("127.0.0.1", srv.server_address[1], timeout=30)
                conn.request("POST", "/billing/checkout", "plan=starter")
                res = conn.getresponse()
                self.assertEqual((res.status, res.getheader("Location")), (303, "https://checkout.test/s"))
                conn.close()
                self.assertEqual(sent["line_items[0][price]"], "price_1")
                # a selling server never serves the API without a key, even before the first sale
                self.assertEqual(self.call_at(base, f"/api/{SPEC['ops'][0]['id']}")[0], 401)
                done = {
                    "type": "checkout.session.completed",
                    "data": {"object": {"id": "cs_1", "subscription": "sub_1", "customer_details": {"email": "a@b.c"}}},
                }
                self.assertEqual(hook(done, secret="whsec_wrong"), 400)
                self.assertEqual(hook(done, ts=int(time.time()) - 3600), 400)
                self.assertEqual(hook(done), 200)
                self.assertEqual(hook(done), 200)  # Stripe retry: still one key
                gate = srv.RequestHandlerClass.gate
                self.assertEqual(len(gate.stored()), 1)
                page = urllib.request.urlopen(base + "/billing/success?session_id=cs_1", timeout=30).read().decode()
                key = page.split("<pre>")[1].split("</pre>")[0]
                self.assertTrue(key.startswith("sk_"))
                again = urllib.request.urlopen(base + "/billing/success?session_id=cs_1", timeout=30).read().decode()
                self.assertNotIn(key, again)  # shown exactly once
                self.assertNotIn(key, (pathlib.Path(t) / "pending-keys.json").read_text(encoding="utf-8"))
                self.assertIsNotNone(gate.identify(f"Bearer {key}"))
                hook({"type": "customer.subscription.deleted", "data": {"object": {"id": "sub_1"}}})
                self.assertIsNone(gate.identify(f"Bearer {key}"))
            finally:
                srv.shutdown()
                srv.server_close()

    def call_at(self, base, path):
        req = urllib.request.Request(base + path, data=b"{}", headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=90) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            with e:
                return e.code, e.headers, e.read()

    def test_user_text_never_becomes_an_option(self):
        op = {
            "prefix": ["x"],
            "fields": [
                {"dest": "v", "flag": None, "kind": "text", "required": True, "scope": "op"},
                {"dest": "o", "flag": "--o", "kind": "text", "scope": "op"},
            ],
        }
        with tempfile.TemporaryDirectory() as t:
            argv, _ = web.build_argv(op, {"v": "--evil", "o": "--also"}, pathlib.Path(t), pathlib.Path(t))
        self.assertEqual(argv[-2:], ["--", "--evil"])
        self.assertIn("--o=--also", argv)


if __name__ == "__main__":
    unittest.main()
